// 1. Declarar el tipo delegate (fuera de la clase o dentro de ella)
public delegate void NotificarDano(int cantidad);

public class Enemigo : MonoBehaviour
{
    // 2. Declarar una variable del tipo delegate
    public NotificarDano alRecibir;

    // 3. Método compatible con la firma
    void MostrarDano(int d) => Debug.Log("Daño: " + d);

    void Start()
    {
        // 4. Instanciar y asignar el método
        alRecibir = new NotificarDano(MostrarDano);
        // Forma corta equivalente:
        alRecibir = MostrarDano;

        // 5. Invocar el delegate
        alRecibir(25);        // imprime: Daño: 25

        // Invocación segura (null-check)
        alRecibir?.Invoke(30); // solo llama si no es null
    }
}

// Los delegates pueden apuntar a VARIOS métodos a la vez (multicast)
public delegate void AlMorir();

public class Jefe : MonoBehaviour
{
    public AlMorir onMuerte;

    void MostrarExplosion() => Debug.Log("¡Boom!");
    void DarPuntos()       => Debug.Log("+500 pts");
    void DesbloquearLogro() => Debug.Log("Logro: Jefe Derrotado");

    void Start()
    {
        // += encadena métodos en la lista de invocación
        onMuerte += MostrarExplosion;
        onMuerte += DarPuntos;
        onMuerte += DesbloquearLogro;

        // Al invocar, se llaman en orden de registro
        onMuerte?.Invoke();
        // Salida:
        // ¡Boom!
        // +500 pts
        // Logro: Jefe Derrotado

        // -= elimina un método de la lista
        onMuerte -= DarPuntos;
    }
}

