public delegate void Efecto();

void Flash()  => Debug.Log("Flash");
void Shake()  => Debug.Log("Shake");
void Freeze() => Debug.Log("Freeze");

void Start()
{
    Efecto fx = Flash;
    fx += Shake;
    fx += Freeze;
    fx -= Flash;
    fx?.Invoke();
}

